package app.fieldwatch.testing

import app.fieldwatch.data.ConfigStore
import app.fieldwatch.domain.DefaultCatalog
import app.fieldwatch.domain.MatchRule
import app.fieldwatch.domain.RadioKind
import app.fieldwatch.domain.RuleKind
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Assume.assumeTrue
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder
import java.io.File

/**
 * P0-8d: release notes list every label and verdict change, generated by [ReleaseNotes].
 *
 * To write or refresh a release's block: `./gradlew testDebugUnitTest --tests '*ReleaseNotesTest*' -PreleaseNotes=X.Y.Z`.
 * The block covers the catalog from where the previous release's notes ended to the current version, and goes into
 * `docs/release-notes/X.Y.Z.md` (which release.yml publishes), keeping the hand-written text around it.
 */
class ReleaseNotesTest {
    @get:Rule
    val golden = GoldenRule()

    @get:Rule
    val tmp = TemporaryFolder()

    /**
     * Everything that changed since Fieldwatch 1.1.32's catalog (v97), as the next release's notes would list it.
     * Each catalog PR re-blesses this golden, so its diff shows exactly the label and verdict changes that PR makes.
     */
    @Test
    fun changesSinceFieldwatch1132() {
        Golden.assertText("release/since-v97.md", ReleaseNotes.block(ReleaseNotes.FIRST_CATALOG, ConfigStore.CATALOG_VERSION))
    }

    /** The committed notes chain from v97 without gaps, and each signatures section is its range's diff. */
    @Test
    fun committedNotesAreCompleteAndMatchTheSnapshots() {
        assertEquals(emptyList<String>(), ReleaseNotes.problems())
    }

    @Test
    fun writeChainsReleasesAndKeepsHandWrittenText() {
        val dir = tmp.newFolder("notes")
        // The first release starts at v97 and ends at the current catalog.
        val first = ReleaseNotes.write("0.1.0", dir)
        assertEquals(97 to ConfigStore.CATALOG_VERSION, ReleaseNotes.declaredRange(first.readText()))
        // Hand-written text above and below the block survives a refresh, byte for byte.
        val handBefore = "# Spectre 0.1.0\n\nFirst release. Thanks, testers.\n\n"
        val handAfter = "\n## Known issues\n\nNone yet.\n"
        val block = first.readText().let { it.substring(it.indexOf(ReleaseNotes.BEGIN)) }
        first.writeText(handBefore + block + handAfter)
        ReleaseNotes.write("0.1.0", dir)
        val refreshed = first.readText()
        assertTrue(refreshed.startsWith(handBefore))
        assertTrue(refreshed.endsWith(handAfter))
        // The next release starts where this one ended.
        val second = ReleaseNotes.write("0.1.1", dir)
        assertEquals(ConfigStore.CATALOG_VERSION to ConfigStore.CATALOG_VERSION, ReleaseNotes.declaredRange(second.readText()))
        assertEquals(emptyList<String>(), ReleaseNotes.problems(dir))
        // A hand-written file with no block gets one appended.
        File(dir, "0.2.0.md").writeText("# Spectre 0.2.0\n\nWritten by hand.\n")
        val third = ReleaseNotes.write("0.2.0", dir)
        assertTrue(third.readText().startsWith("# Spectre 0.2.0\n\nWritten by hand.\n"))
        assertEquals(emptyList<String>(), ReleaseNotes.problems(dir))
    }

    @Test
    fun problemsCatchATamperedListAGapAndAMissingBlock() {
        val dir = tmp.newFolder("bad")
        val notes = ReleaseNotes.write("0.1.0", dir)
        val text = notes.readText()
        val smartTags = text.lines().single { it.startsWith("- **Samsung SmartTags** (finder): stopped matching on") }
        notes.writeText(text.replace(smartTags + "\n", ""))
        assertTrue(ReleaseNotes.problems(dir).single().contains("aren't the v97 → v${ConfigStore.CATALOG_VERSION} diff"))
        // A release that skips catalog versions: it starts after where 0.1.0 ended.
        val gap = File(dir, "0.1.1.md")
        gap.writeText("# x\n" + ReleaseNotes.BEGIN + "\n<!-- generated: catalog v${ConfigStore.CATALOG_VERSION + 5} -> v${ConfigStore.CATALOG_VERSION + 5} -->\n")
        assertTrue(ReleaseNotes.problems(dir).any { it.contains("0.1.1.md: starts at") })
        File(dir, "0.2.0.md").writeText("Only hand-written.\n")
        assertTrue(ReleaseNotes.problems(dir).any { it.contains("0.2.0.md: no generated block") })
    }

    /** P1-B12e: an any-radio rule replaced by the same rule on one radio reads as a narrowing. */
    @Test
    fun aNarrowedRadioReadsAsOneChange() {
        val stock = DefaultCatalog.fleets()
        val tile = stock.single { it.id == "fleet-tile" }
        val anyRadio = MatchRule(RuleKind.OUI, text = "12:34:56")
        val before = stock.map { if (it.id == "fleet-tile") it.copy(rules = it.rules + anyRadio) else it }
        val after = stock.map { if (it.id == "fleet-tile") it.copy(rules = it.rules + anyRadio.copy(radio = RadioKind.WIFI)) else it }
        val line = ReleaseNotes.signatures(1, 2, before, after).lines().single { it.startsWith("- **${tile.name}**") }
        assertTrue(line, line.contains("now Wi-Fi only: oui \"12:34:56\""))
        assertFalse(line, line.contains("stopped matching") || line.contains("now also matches"))
        // Split across both radios, or switched off as well: not a plain narrowing.
        val split = stock.map { if (it.id == "fleet-tile") it.copy(rules = it.rules + anyRadio.copy(radio = RadioKind.WIFI) + anyRadio.copy(radio = RadioKind.BLE)) else it }
        val splitLine = ReleaseNotes.signatures(1, 2, before, split).lines().single { it.startsWith("- **${tile.name}**") }
        assertFalse(splitLine, splitLine.contains(" only:"))
        val offToo = stock.map { if (it.id == "fleet-tile") it.copy(rules = it.rules + anyRadio.copy(radio = RadioKind.WIFI, enabled = false)) else it }
        val offLine = ReleaseNotes.signatures(1, 2, before, offToo).lines().single { it.startsWith("- **${tile.name}**") }
        assertFalse(offLine, offLine.contains(" only:"))
    }

    /** The diff names cluster settings and switched rules plainly. */
    @Test
    fun clusterSettingsAndRuleSwitchesAreListed() {
        val stock = DefaultCatalog.fleets()
        val tile = stock.single { it.id == "fleet-tile" }
        val edited = stock.map {
            if (it.id != "fleet-tile") it
            else it.copy(minPeers = 3, clusterByOui = !it.clusterByOui, rules = it.rules.map { r -> if (r.kind == RuleKind.SERVICE_UUID) r.copy(enabled = false) else r })
        }
        val text = ReleaseNotes.signatures(1, 2, stock, edited)
        val line = text.lines().single { it.startsWith("- **${tile.name}**") }
        assertTrue(line, line.contains("needs 3 peers (was ${tile.minPeers})"))
        assertTrue(line, line.contains("clusters by OUI"))
        assertTrue(line, line.contains("switched off"))
        assertTrue(line, !line.contains("stopped matching"))
    }

    /** A verdict changes when a hit's class or attention changes, not only its signature. */
    @Test
    fun aReclassedHitIsAVerdictChange() {
        val stock = DefaultCatalog.fleets()
        val edited = stock.map { if (it.id == "fleet-airtag") it.copy(kind = app.fieldwatch.domain.SignatureClass.OTHER) else it }
        val text = ReleaseNotes.verdicts(stock, edited)
        assertTrue(text, text.contains("Target: AirTag, Offline Finding status 0x10: was Apple AirTags (finder), now Apple AirTags (other)."))
    }

    /** Writes a release's block when asked (see the class doc); skipped otherwise. */
    @Test
    fun writeReleaseNotes() {
        val version = System.getProperty("spectre.releaseNotes").orEmpty()
        assumeTrue("Set -PreleaseNotes=X.Y.Z to write release notes.", version.isNotBlank())
        val file = ReleaseNotes.write(version)
        println("Release notes: wrote the generated block to ${file.name}")
        assertEquals(emptyList<String>(), ReleaseNotes.problems())
    }
}
